 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    # A solid, non-background line is the barrier toward which objects move.
    barrier = None
    for r, row in enumerate(grid):
        if row[0] != 0 and all(v == row[0] for v in row):
            barrier = ("row", r, row[0])
            break
    if barrier is None:
        for c in range(w):
            color = grid[0][c]
            if color != 0 and all(grid[r][c] == color for r in range(h)):
                barrier = ("col", c, color)
                break
    if barrier is None:
        return [row[:] for row in grid]

    axis, line, barrier_color = barrier
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == barrier_color or (r, c) in seen:
                continue
            cells = []
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            objects.append((color, cells))

    # Process nearest-to-barrier objects first, so each object settles onto
    # the barrier or onto objects already settled in front of it.
    if axis == "row":
        toward_positive = line == 0
        if toward_positive:
            objects.sort(key=lambda obj: min(r for r, _ in obj[1]))
            step = 1
        else:
            objects.sort(key=lambda obj: max(r for r, _ in obj[1]), reverse=True)
            step = -1
    else:
        toward_positive = line == 0
        if toward_positive:
            objects.sort(key=lambda obj: min(c for _, c in obj[1]))
            step = 1
        else:
            objects.sort(key=lambda obj: max(c for _, c in obj[1]), reverse=True)
            step = -1

    out = [[0] * w for _ in range(h)]
    for i in range(w):
        out[line][i] = barrier_color
    for j in range(h):
        out[j][line] = barrier_color if axis == "col" else out[j][line]

    for color, cells in objects:
        dr = step if axis == "row" else 0
        dc = step if axis == "col" else 0
        while True:
            shifted = [(r + dr, c + dc) for r, c in cells]
            if any(r < 0 or r >= h or c < 0 or c >= w for r, c in shifted):
                break
            # Don't cross or occupy the barrier line.
            if any((axis == "row" and r == line) or (axis == "col" and c == line) for r, c in shifted):
                break
            if any(out[r][c] != 0 for r, c in shifted):
                break
            cells = shifted
        for r, c in cells:
            out[r][c] = color
    return out
